	@Test
	@Timeout(120)
	void finiteAnchorsStayLocalAndSelfLoopProbesStayBound(
			@TempDir(cleanup = CleanupMode.NEVER) Path evidence) throws Exception {
		ThemeQueryBenchmark benchmark = new ThemeQueryBenchmark();
		benchmark.themeName = Theme.SOCIAL_MEDIA.name();
		benchmark.z_queryIndex = 7;
		benchmark.sketchEstimatorEnabled = true;
		benchmark.queryExplanationLevel = "Optimized";
		benchmark.loadOnlySelectedTheme = true;

		String previousProfiling = System.getProperty(PROFILING_PROPERTY);
		System.setProperty(PROFILING_PROPERTY, "true");
		try {
			benchmark.setup();
			TupleExpr optimized = benchmark.explainOptimizedTupleExpr();
			captureCandidateEvidence(optimized, evidence);
			String plan = new QueryModelTreeToGenericPlanNode(optimized, Set.of(), Explanation.Level.Optimized)
					.getGenericPlanNode()
					.toString();
			String renderedQuery = new TupleExprIRRenderer().render(optimized);

			assertBefore(renderedQuery, PAIR_VALUES, MUTUAL_FOLLOW,
					"q7 should place the finite pair anchor before expanding mutual follow pairs\n" + plan);
			assertBefore(renderedQuery, PAIR_VALUES, MUTUAL_FOLLOW_PROBE,
					"q7 should place the finite pair anchor before the mutual-follow EXISTS probe\n" + plan);
			assertTrue(renderedQuery.contains(OPT_NAME_VALUES),
					"q7 should materialize the finite optName anchor as VALUES\n"
							+ renderedQuery + "\n" + plan);
			assertTrue(renderedQuery.contains(OPT_NAME_FILTER),
					"q7 should retain the optName IN filter while the anchor evidence is heuristic\n"
							+ renderedQuery + "\n" + plan);
			assertMutualFollowProbeIsBound(plan);
			assertNoUnboundSelfLoopFollows(optimized);
			assertBoundTriplePrefix(plan);
			assertRootPlannedWorkRowsAtMost(plan, MAX_ROOT_PLANNED_WORK_ROWS,
					"q7 anchors should keep the total planned work bounded (no broad follows scan)");
		} finally {
			try {
				benchmark.tearDown();
			} finally {
				restoreProperty(PROFILING_PROPERTY, previousProfiling);
			}
		}
	}


	/** Diagnostic-only capture after the existing planning call, before any original quality assertion. */
	private static void captureCandidateEvidence(TupleExpr optimized, Path evidence) throws IOException {
		List<QueryModelNode> nodes = new ArrayList<>();
		optimized.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (node instanceof TupleExpr) {
					nodes.add(node);
				}
				super.meetNode(node);
			}
		});
		Map<QueryModelNode, Integer> ordinals = new IdentityHashMap<>();
		for (int index = 0; index < nodes.size(); index++) {
			ordinals.put(nodes.get(index), index);
		}
		StringBuilder inventory = new StringBuilder();
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(optimized,
				EmptyBindingSet.getInstance());
		String text = null;
		String json = null;
		for (QueryModelNode node : nodes) {
			QueryModelNode parent = node.getParentNode();
			while (parent != null && !(parent instanceof TupleExpr)) {
				parent = parent.getParentNode();
			}
			inventory.append("node=").append(ordinals.get(node)).append(" parent=")
					.append(parent == null ? "none" : ordinals.get(parent))
					.append(" type=").append(node.getClass().getSimpleName());
			if (node instanceof StatementPattern pattern) {
				inventory.append(" scope=").append(pattern.getScope())
						.append(" S=").append(term(pattern.getSubjectVar()))
						.append(" P=").append(term(pattern.getPredicateVar()))
						.append(" O=").append(term(pattern.getObjectVar()))
						.append(" C=").append(term(pattern.getContextVar()))
						.append(" Sinput=").append(analysis.bindingState(pattern.getSubjectVar(), analysis.contextAt(pattern)))
						.append(" Oinput=").append(analysis.bindingState(pattern.getObjectVar(), analysis.contextAt(pattern)));
			} else if (node instanceof BindingSetAssignment assignment) {
				inventory.append(" valuesOutputs=").append(new TreeSet<>(assignment.getBindingNames()));
			} else if (node instanceof Difference difference) {
				var left = analysis.outputFacts(difference.getLeftArg());
				var right = analysis.outputFacts(difference.getRightArg());
				inventory.append(" leftGuaranteedKnown=").append(left.guaranteedOutputsKnown())
						.append(" leftGuaranteed=").append(new TreeSet<>(left.guaranteedOutputs()))
						.append(" rightGuaranteedKnown=").append(right.guaranteedOutputsKnown())
						.append(" rightGuaranteed=").append(new TreeSet<>(right.guaranteedOutputs()));
			}
			for (String key : List.of("optimizer.cascadesMode", "optimizer.cascadesCompleteness",
					"optimizer.cascadesApproximate", "optimizer.cascadesLimitCauses", "optimizer.cascadesPlanCacheHit",
					"optimizer.pipelinePlanCacheHit", "optimizer.semiAntiAlgorithm", "optimizer.semiAntiKind",
					"optimizer.filterAlgorithmHint", "optimizer.physicalJoinImplementation", "optimizer.joinAlgorithmHint",
					"plannedEstimateSource", "plannedLookupComponents", "plannedIndexAccessMode", "plannedCostScope",
					"optimizer.costEventPhase", "optimizer.costEventCostScope", "optimizer.costEventContextFingerprint",
					"optimizer.dependentCostSource")) {
				inventory.append(' ').append(key).append('=').append(node.getStringMetricPlanned(key));
			}
			for (String key : List.of("optimizer.cascadesWorkUnits", "optimizer.cascadesCandidateEvaluations",
					"optimizer.cascadesRuleWork", "optimizer.cascadesPredicateProbes", "optimizer.cascadesDphypPairProbes",
					"optimizer.cascadesPartitionProbes", "optimizer.cascadesRetainedCandidates",
					"optimizer.cascadesRootCostWorkRows", "optimizer.costEventOrdinal", "optimizer.costEventPrefixRows",
					"optimizer.costEventRows", "optimizer.costEventObjective", "plannedWorkRows", "plannedAccessRows",
					"plannedRepeatedInvocations", "plannedIndexPrefixLength", "plannedCostSequentialRows",
					"plannedCostRandomSeeks", "plannedCostIteratorOpens", "plannedCostExpressionEvaluations",
					"plannedCostHashBuildRows", "plannedCostHashProbeRows", "plannedCostResultRows")) {
				inventory.append(' ').append(key).append('=').append(node.getDoubleMetricPlanned(key));
			}
			inventory.append('\n');
			if (text == null) {
				text = node.getStringMetricPlanned("optimizer.packedExplanation");
			}
			if (json == null) {
				json = node.getStringMetricPlanned("optimizer.packedExplanationJson");
			}
		}
		Files.writeString(evidence.resolve("selected-node-inventory.txt"), inventory);
		Files.writeString(evidence.resolve("packed-candidates.txt"), text == null ? "missing\n" : text);
		Files.writeString(evidence.resolve("packed-candidates.json"), json == null ? "null\n" : json);
		Files.writeString(evidence.resolve("capture-status.txt"), "afterOriginalOptimize=true\nextraQueries=0\n"
				+ "extraSessions=0\ntextPresent=" + (text != null) + "\njsonPresent=" + (json != null)
				+ "\nmissingDoubleMetricSentinel=-1\n");
		System.out.println("Q7 candidate evidence: " + evidence);
	}

	private static String term(Var variable) {
		return variable == null ? "absent" : variable.hasValue() ? variable.getValue().toString() : "?" + variable.getName();
	}

	private static void assertBefore(String value, List<String> firsts, String second, String message) {
		int firstIndex = firsts.stream()
				.mapToInt(value::indexOf)
				.filter(index -> index >= 0)
				.min()
				.orElse(-1);
		int secondIndex = value.indexOf(second);
		if (firstIndex < 0 || secondIndex < 0 || firstIndex >= secondIndex) {
			throw new AssertionError(message + "\nExpected one of `" + firsts + "` before `" + second + "` in:\n"
					+ value);
		}
	}

	private static void assertBoundTriplePrefix(String plan) {
		boolean found = false;
		for (String pattern : statementPatternsForPredicate(plan, "http://example.com/theme/social/follows")) {
			String header = pattern.lines().findFirst().orElse("");
			if (header.contains("plannedLookupComponents=[S, P, O]")) {
				assertTrue(header.contains("plannedIndexAccessMode=prefixScan")
						&& header.contains("plannedIndexPrefixLength=3.00"),
						"A bound triple with an unbound context must retain its three-component native prefix\n"
								+ pattern);
				found = true;
			}
		}
		assertTrue(found, "q7 must retain a bound triple-prefix probe\n" + plan);
	}

	private static void assertRootPlannedWorkRowsAtMost(String plan, double maxRows, String message) {
		Matcher matcher = PLANNED_WORK_ROWS.matcher(plan);
		assertTrue(matcher.find(), "Expected root plannedWorkRows metric in:\n" + plan);
		double workRows = parsePlanRows(matcher.group(1));
		assertTrue(workRows <= maxRows,
				message + "\nExpected plannedWorkRows <= " + maxRows + " but got " + workRows + "\n" + plan);
	}

	private static double parsePlanRows(String value) {
		String trimmed = value.trim();
		double multiplier = 1.0d;
		if (trimmed.endsWith("K")) {
			multiplier = 1_000.0d;
			trimmed = trimmed.substring(0, trimmed.length() - 1);
		} else if (trimmed.endsWith("M")) {
			multiplier = 1_000_000.0d;
			trimmed = trimmed.substring(0, trimmed.length() - 1);
		} else if (trimmed.endsWith("B")) {
			multiplier = 1_000_000_000.0d;
			trimmed = trimmed.substring(0, trimmed.length() - 1);
		}
		return Double.parseDouble(trimmed) * multiplier;
	}

	private static void assertMutualFollowProbeIsBound(String plan) {
		for (String pattern : statementPatternsForPredicate(plan, "http://example.com/theme/social/follows")) {
			boolean mutualFollow = pattern.contains("s: Var (name=u)") && pattern.contains("o: Var (name=v)");
			boolean anyUnbound = pattern.contains("bindingState=unbound");
			assertTrue(!mutualFollow || !anyUnbound,
					"q7 mutual-follow probe should run with both pair-anchor endpoints bound, not scan follows:\n"
							+ pattern + "\nFull plan:\n" + plan);
		}
	}

	private static void assertNoUnboundSelfLoopFollows(TupleExpr optimized) {
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(optimized,
				EmptyBindingSet.getInstance());
		optimized.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern pattern) {
				if (!pattern.getPredicateVar().hasValue()
						|| !"http://example.com/theme/social/follows"
								.equals(pattern.getPredicateVar().getValue().stringValue())
						|| !"v".equals(pattern.getSubjectVar().getName())
						|| !"v".equals(pattern.getObjectVar().getName())) {
					return;
				}
				var input = analysis.contextAt(pattern);
				boolean bound = analysis.bindingState(pattern.getSubjectVar(),
						input) == QueryAlgebraBindingAnalysis.BindingState.BOUND
						&& analysis.bindingState(pattern.getObjectVar(),
								input) == QueryAlgebraBindingAnalysis.BindingState.BOUND;
				assertTrue(bound,
						"q7 self-loop anti-join should probe with ?v bound, not scan all follows rows:\n" + pattern
								+ "\nFull plan:\n" + optimized);
			}
		});
	}

	@Test
	void unrelatedExplainMetadataCannotHideAnUnboundSelfLoop() {
		StatementPattern selfLoop = new StatementPattern(Var.of("v"),
				Var.of("predicate",
						SimpleValueFactory.getInstance().createIRI("http://example.com/theme/social/follows")),
				Var.of("v"));
		selfLoop.getObjectVar().setStringMetricPlanned("optimizer.objectGuarantee", "RdfTermDomain[IRI]");
		assertThrows(AssertionError.class, () -> assertNoUnboundSelfLoopFollows(selfLoop));
		BindingSetAssignment anchor = new BindingSetAssignment();
		anchor.setBindingSets(List.of(new ListBindingSet(List.of("v"),
				SimpleValueFactory.getInstance().createIRI("urn:bound-user"))));
		assertNoUnboundSelfLoopFollows(new Join(anchor, selfLoop.clone()));
	}

	private static List<String> statementPatternsForPredicate(String plan, String predicate) {
		List<String> patterns = new ArrayList<>();
		StringBuilder current = null;
		for (String line : plan.split("\\R")) {
			if (line.contains("StatementPattern (")) {
				addPatternIfPredicateMatches(patterns, current, predicate);
				current = new StringBuilder();
			}
			if (current != null) {
				current.append(line).append('\n');
			}
		}
		addPatternIfPredicateMatches(patterns, current, predicate);
		return patterns;
	}

	private static void addPatternIfPredicateMatches(List<String> patterns, StringBuilder current, String predicate) {
		if (current == null) {
			return;
		}
		String pattern = current.toString();
		if (pattern.contains("value=" + predicate)) {
			patterns.add(pattern);
		}
	}

	private static void restoreProperty(String name, String previousValue) {
		if (previousValue == null) {
			System.clearProperty(name);
		} else {
			System.setProperty(name, previousValue);
		}
	}
